            </View>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={`Delete lesson ${session.title}`}
              hitSlop={8}
              onPress={(event) => { event.stopPropagation(); confirmDelete(session); }}
              style={({ pressed }) => [styles.deleteButton, pressed && styles.deletePressed]}
