export interface SaveSharedSessionOptions {
	model?: Model<any>;
	thinkingLevel?: SessionMetadata["thinkingLevel"];
}

export interface SharedSessionUrlResult {
	url: string;
	mode: ShareLinkMode;
	fallback: boolean;
}

export type SharedSessionLoadResult =
	| { ok: true; session: SharedSession; source: "hash" | "cache" | "server" }
	| { ok: false; reason: "not-found" | "invalid-link" | "mismatch" | "server-error" | "network"; message: string; status?: number };

// Whether the caller should warn the user that a share exposes the transcript
// publicly before creating the link. Returns false once the user has
// acknowledged the warning (so it is a one-time prompt, not a nag) and for
// modes that keep the data on-device (`local-short`).
export function shouldWarnBeforePublicShare(
	mode: ShareLinkMode = loadKeatingUiSettings().shareLinkMode,
	acknowledged: boolean = loadKeatingUiSettings().shareWarningAcknowledged,
): boolean {
	return shareModeExposesDataPublicly(mode) && !acknowledged;
}

function serializeModel(model: Model<any> | undefined): SharedModelInfo {
	const fallback = model ?? DEFAULT_MODEL;
	const api = "api" in fallback && typeof fallback.api === "string" ? fallback.api : undefined;
	const baseUrl = "baseUrl" in fallback && typeof fallback.baseUrl === "string" ? fallback.baseUrl : undefined;
	return {
		provider: fallback.provider,
		id: fallback.id,
		name: fallback.name,
		api,
		baseUrl,
	};
}

function normalizeSharedSession(parsed: Partial<SharedSession> | null): SharedSession | null {
	if (!parsed?.id || !Array.isArray(parsed.messages)) return null;
	const messages = sanitizeMessagesForShare(parsed.messages);
	return {
		...parsed,
		schemaVersion: 2,
		title: typeof parsed.title === "string" && parsed.title.trim() ? parsed.title : sessionTitle(messages),
		createdAt: typeof parsed.createdAt === "string" ? parsed.createdAt : new Date().toISOString(),
		sharedAt: typeof parsed.sharedAt === "string" ? parsed.sharedAt : new Date().toISOString(),
		messageCount: messages.length,
		model: parsed.model?.provider && parsed.model?.id ? parsed.model : undefined,
		thinkingLevel: parsed.thinkingLevel ?? "medium",
		messages,
	} as SharedSession;
}

function decodeSharedSession(value: string): SharedSession | null {
	return normalizeSharedSession(decodeSharedSessionPayload(value));
}

function isShareableRole(role: unknown) {
	return role === "user" || role === "user-with-attachments" || role === "assistant";
}

function textFromContent(content: unknown): string {
	if (typeof content === "string") return content;
	if (!Array.isArray(content)) return "";
	return content
		.filter((part) => part?.type === "text" && typeof part.text === "string")
		.map((part) => part.text)
		.join("\n");
}

export function sanitizeMessagesForShare(messages: AgentMessage[]): AgentMessage[] {
	return messages.flatMap((message) => {
		const role = (message as any).role;
		if (!isShareableRole(role)) return [];

		const text = textFromContent((message as any).content).trim();
		if (!text) return [];

		return [{
			...message,
			role,
			content: [{ type: "text", text }],
		} as AgentMessage];
	});
}

function readShareIndex(): string[] {
	try {
		const raw = localStorage.getItem(SHARE_INDEX_KEY);
		const parsed = raw ? JSON.parse(raw) : [];
		return Array.isArray(parsed) ? parsed.filter((id) => typeof id === "string") : [];
	} catch {
		return [];
	}
}

function writeShareIndex(ids: string[]) {
	localStorage.setItem(SHARE_INDEX_KEY, JSON.stringify(Array.from(new Set(ids))));
}

export function saveSharedSession(messages: AgentMessage[], createdAt: string, options: SaveSharedSessionOptions = {}): SharedSession {
	const sanitizedMessages = sanitizeMessagesForShare(messages);
	if (sanitizedMessages.length === 0) {
		throw new Error("There is no shareable text in this session yet");
	}

	const id = createSessionId();
	const shared: SharedSession = {
		id,
		schemaVersion: 2,
		title: sessionTitle(sanitizedMessages),
		createdAt,
		sharedAt: new Date().toISOString(),
		messageCount: sanitizedMessages.length,
		model: serializeModel(options.model),
		thinkingLevel: options.thinkingLevel ?? "medium",
		messages: sanitizedMessages,
	};

	cacheSharedSession(shared);
	return shared;
}

function cacheSharedSession(shared: SharedSession) {
	localStorage.setItem(`${SHARE_KEY_PREFIX}${shared.id}`, JSON.stringify(shared));
	writeShareIndex([shared.id, ...readShareIndex()]);
}

export function loadSharedSession(id: string): SharedSession | null {
	const raw = localStorage.getItem(`${SHARE_KEY_PREFIX}${id}`);
	if (!raw) return null;

	try {
		const parsed = JSON.parse(raw) as SharedSession;
		if (parsed?.id !== id) return null;
		return normalizeSharedSession(parsed);
	} catch {
		return null;
	}
}

export function listCachedSharedSessions(): SharedSession[] {
	return readShareIndex()
		.map((id) => loadSharedSession(id))
		.filter((session): session is SharedSession => Boolean(session));
}

function sharedSessionPath(id: string, origin: string) {
	const url = new URL(`/s/${encodeURIComponent(id)}`, origin);
	return url.toString();
}

async function publishSharedSession(shared: SharedSession): Promise<SharedSession> {
	// The server assigns its own compact share id and validates any client id
	// against /^[A-Za-z0-9_-]{8,32}$/. `shared.id` is a 36-char UUID from
	// createSessionId(), which fails that check and 400s. Drop it before upload
	// and let the server mint the id it returns.
	const { id: _localId, ...payload } = shared;
	const response = await fetch("/api/share", {
		method: "POST",
		headers: { "content-type": "application/json" },
		body: JSON.stringify(payload),
	});
	if (!response.ok) {
		const detail = await response.text().catch(() => "");
		throw new Error(`Share storage returned ${response.status}${detail ? `: ${detail.slice(0, 240)}` : ""}`);
	}
	const result = await response.json() as { id?: unknown };
	if (typeof result.id !== "string" || !result.id) throw new Error("Share storage did not return an id");
	return { ...shared, id: result.id };
}

export async function sharedSessionUrl(
	shared: SharedSession,
	origin: string,
	mode: ShareLinkMode = loadKeatingUiSettings().shareLinkMode,
): Promise<SharedSessionUrlResult> {
	if (mode === "local-short") {
		cacheSharedSession(shared);
		return { url: sharedSessionPath(shared.id, origin), mode, fallback: false };
	}

	if (mode === "compressed-hash") {
		const url = new URL(`/s/${encodeURIComponent(shared.id)}`, origin);
		url.hash = `${SHARE_HASH_PARAM}=${encodeSharedSession(shared)}`;
		return { url: url.toString(), mode, fallback: false };
	}

	try {
		const published = await publishSharedSession(shared);
		cacheSharedSession(published);
		return { url: sharedSessionPath(published.id, origin), mode, fallback: false };
	} catch (error) {
		console.warn("Portable share storage failed:", error);
		throw new Error("Could not save the session to the share server. Try again, or switch Settings → Share Links to Compressed snapshot if you explicitly want a long self-contained link.");
	}
}

async function fetchSharedSessionResult(id: string): Promise<SharedSessionLoadResult> {
	try {
		const response = await fetch(`/api/share/${encodeURIComponent(id)}`);
		if (response.status === 404) {
			return { ok: false, reason: "not-found", status: response.status, message: "Shared session was not found on the share server." };
		}
		if (!response.ok) {
			const detail = await response.text().catch(() => "");
			return {
				ok: false,
				reason: "server-error",
				status: response.status,
				message: `Share server returned ${response.status}${detail ? `: ${detail.slice(0, 240)}` : ""}`,
			};
		}
		const shared = normalizeSharedSession(await response.json() as SharedSession);
		if (!shared) {
			return { ok: false, reason: "invalid-link", message: "Share server returned an invalid shared session payload." };
		}
		if (shared.id !== id) {
			return { ok: false, reason: "mismatch", message: "Share server returned a different session id than the link requested." };
		}
		cacheSharedSession(shared);
		return { ok: true, session: shared, source: "server" };
	} catch (error) {
		return {
			ok: false,
			reason: "network",
			message: error instanceof Error ? error.message : "Could not reach the share server.",
		};
	}
}

export async function loadSharedSessionResultFromUrl(id: string, hash: string): Promise<SharedSessionLoadResult> {
	const params = new URLSearchParams(hash.startsWith("#") ? hash.slice(1) : hash);
	const encoded = params.get(SHARE_HASH_PARAM);
	if (!encoded) {
		const cached = loadSharedSession(id);
		if (cached) return { ok: true, session: cached, source: "cache" };
		return await fetchSharedSessionResult(id);
	}

	const shared = decodeSharedSession(encoded);
	if (!shared) {
		const cached = loadSharedSession(id);
		if (cached) return { ok: true, session: cached, source: "cache" };
		return { ok: false, reason: "invalid-link", message: "This share link contains an unreadable session snapshot." };
	}
	if (shared.id !== id) {
		const cached = loadSharedSession(id);
		if (cached) return { ok: true, session: cached, source: "cache" };
		return { ok: false, reason: "mismatch", message: "This share link snapshot does not match the session id in the URL." };
	}
	cacheSharedSession(shared);
	return { ok: true, session: shared, source: "hash" };
}

export async function loadSharedSessionFromUrl(id: string, hash: string): Promise<SharedSession | null> {
	const result = await loadSharedSessionResultFromUrl(id, hash);
	return result.ok ? result.session : null;
}

export async function forkSharedSession(shared: SharedSession): Promise<string> {
	const id = createSessionId();
	const now = new Date().toISOString();
	const title = `${shared.title} (fork)`;
	const messages = sanitizeMessagesForShare(shared.messages);
	const model = shared.model ? {
		...DEFAULT_MODEL,
		...shared.model,
		provider: shared.model.provider as any,
		api: (shared.model.api ?? DEFAULT_MODEL.api) as any,
	} : DEFAULT_MODEL;

	const metadata: SessionMetadata = {
		id,
		title,
		createdAt: now,
		lastModified: now,
		messageCount: messages.length,
		usage: sessionUsage(messages),
		thinkingLevel: shared.thinkingLevel ?? "medium",
		...sessionModelMetadata(model),
		preview: sessionPreview(messages),
		searchText: sessionSearchText(messages),
	};
	const data: SessionData = {
		id,
		title,
		model,
		thinkingLevel: shared.thinkingLevel ?? "medium",
		messages,
		createdAt: now,
		lastModified: now,
	};

	await sessions.save(data, metadata);
	return id;
}
import { gzipSync, gunzipSync } from "fflate";
import type { SharedModelInfo, SharedSession } from "./shared-sessions";

// Hash-embedded share links carry the whole session in the URL fragment. To keep
// those links short the payload is gzip-compressed and base64url-encoded. This
// module is intentionally dependency-light (only `fflate` plus type-only
// imports) so the encode/decode path is pure and unit-testable without pulling
// in the storage/runtime side of `shared-sessions.ts`.

export const COMPRESSED_PREFIX = "gz.";
export const JSON_PREFIX = "json.";

export function bytesToBase64Url(bytes: Uint8Array): string {
	let binary = "";
	for (const byte of bytes) binary += String.fromCharCode(byte);
	return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

export function base64UrlToBytes(value: string): Uint8Array {
	const base64 = value.replace(/-/g, "+").replace(/_/g, "/").padEnd(Math.ceil(value.length / 4) * 4, "=");
	const binary = atob(base64);
	return Uint8Array.from(binary, (char) => char.charCodeAt(0));
}

// Gzip via the bundled `fflate` codec rather than the optional `CompressionStream`
// Web API. `CompressionStream` is unavailable in several shipping browsers and
// webviews (older Safari/Firefox, some embedded/non-secure contexts), and the
// previous implementation silently returned the input uncompressed there — which
// is why share links were long and "not compressed at all". fflate is
// deterministic, synchronous, and produces/consumes standard gzip, so links
// compress the same way everywhere and stay backward-compatible with existing
// `gz.` gzip links created by `CompressionStream`.
function gzipBytes(bytes: Uint8Array): Uint8Array {
	return gzipSync(bytes, { level: 9 });
}

function gunzipBytes(bytes: Uint8Array): Uint8Array {
	return gunzipSync(bytes);
}

export function textFromContent(content: unknown): string {
	if (typeof content === "string") return content;
	if (!Array.isArray(content)) return "";
	return content
		.filter((part) => part?.type === "text" && typeof part.text === "string")
		.map((part) => part.text)
		.join("\n");
}

// Only the fields the shared view and fork flow actually need. Assistant
// messages otherwise carry large provider/model/usage/diagnostics metadata that
// never renders in a shared session, so we drop it before encoding to keep the
// pre-compression payload (and therefore the URL) as small as possible.
interface MinimalSharedMessage {
	role: string;
	content: [{ type: "text"; text: string }];
}

interface MinimalSharedSession {
	id: string;
	schemaVersion: 2;
	title: string;
	createdAt: string;
	sharedAt: string;
	messageCount: number;
	model?: SharedModelInfo;
	thinkingLevel?: SharedSession["thinkingLevel"];
	messages: MinimalSharedMessage[];
}

export function minifySharedSession(shared: SharedSession): MinimalSharedSession {
	return {
		id: shared.id,
		schemaVersion: 2,
		title: shared.title,
		createdAt: shared.createdAt,
		sharedAt: shared.sharedAt,
		messageCount: shared.messageCount,
		model: shared.model,
		thinkingLevel: shared.thinkingLevel,
		messages: shared.messages.map((message) => ({
			role: (message as any).role,
			content: [{ type: "text", text: textFromContent((message as any).content) }],
		})),
	};
}

export function encodeSharedSession(shared: SharedSession): string {
	const bytes = new TextEncoder().encode(JSON.stringify(minifySharedSession(shared)));
	try {
		const compressed = gzipBytes(bytes);
		if (compressed.length < bytes.length) return `${COMPRESSED_PREFIX}${bytesToBase64Url(compressed)}`;
	} catch {
		// Fall through to uncompressed JSON encoding (e.g. unexpected codec failure).
	}
	return `${JSON_PREFIX}${bytesToBase64Url(bytes)}`;
}

// Returns the parsed (but not normalized) shared-session payload, or null if the
// value cannot be decoded. Supports `gz.` (gzip), `json.` (uncompressed), and
// bare/legacy base64url payloads.
export function decodeSharedSessionPayload(value: string): Partial<SharedSession> | null {
	try {
		const isCompressed = value.startsWith(COMPRESSED_PREFIX);
		const isJson = value.startsWith(JSON_PREFIX);
		const encoded = isCompressed || isJson ? value.slice(value.indexOf(".") + 1) : value;
		const bytes = base64UrlToBytes(encoded);
		const decoded = isCompressed ? gunzipBytes(bytes) : bytes;
		return JSON.parse(new TextDecoder().decode(decoded)) as Partial<SharedSession>;
	} catch {
		return null;
	}
}
import type { SessionData, SessionMetadata } from "../types/session";
import { sessionModelMetadata, sessionPreview, sessionSearchText, sessionUsage } from "../hooks/session-metadata";
import type { KeatingStorageImportResult, KeatingStoragePortableData } from "./storage";
import type { KeatingSandboxPortableBundle } from "./sandbox-export";
import { getInitPromise, keatingStorage, sessions } from "../hooks/keating-storage";
import { buildSandboxPortableBundle, importSandboxPortableBundle } from "./sandbox-export";

export interface KeatingPortableSession {
	data: SessionData;
	metadata: SessionMetadata;
}

export interface KeatingPortableDataBundle {
	schemaVersion: 1;
	kind: "keating-portable-data";
	generatedAt: string;
	sessions: KeatingPortableSession[];
	storage: KeatingStoragePortableData;
	sandbox?: KeatingSandboxPortableBundle;
}

export interface KeatingPortableDataSources {
	sessions: KeatingPortableSession[];
	storage: KeatingStoragePortableData;
	sandbox?: KeatingSandboxPortableBundle;
	generatedAt?: string;
}

export interface KeatingPortableImportResult extends KeatingStorageImportResult {
	sessions: number;
	sandboxFilesImported: number;
	sandboxSnapshotsImported: number;
	sandboxCommitsImported: number;
}

function metadataForSession(data: SessionData, existing?: Partial<SessionMetadata>): SessionMetadata {
	return {
		id: data.id,
		title: data.title,
		parentSessionId: data.parentSessionId,
		forkedAt: data.forkedAt,
		createdAt: data.createdAt,
		lastModified: data.lastModified,
		messageCount: data.messages.length,
		usage: existing?.usage ?? sessionUsage(data.messages),
		thinkingLevel: data.thinkingLevel,
		...sessionModelMetadata(data.model),
		preview: existing?.preview ?? sessionPreview(data.messages),
		searchText: existing?.searchText ?? sessionSearchText(data.messages),
		aiGeneratedTitle: existing?.aiGeneratedTitle ?? data.aiGeneratedTitle,
		generatedAlternative: existing?.generatedAlternative ?? data.generatedAlternative,
		hiddenAlternative: existing?.hiddenAlternative ?? data.hiddenAlternative,
		alternativeForMessageTimestamp: existing?.alternativeForMessageTimestamp ?? data.alternativeForMessageTimestamp,
		responsePreference: existing?.responsePreference ?? data.responsePreference,
	};
}

export function parseKeatingPortableDataBundle(value: unknown): KeatingPortableDataBundle {
	const bundle = value && typeof value === "object" ? value as KeatingPortableDataBundle : null;
	if (!bundle || bundle.schemaVersion !== 1 || bundle.kind !== "keating-portable-data") {
		throw new Error("Unsupported Keating portable data bundle.");
	}
	return bundle;
}

export function buildKeatingPortableDataBundleFromSources(sources: KeatingPortableDataSources): KeatingPortableDataBundle {
	return {
		schemaVersion: 1,
		kind: "keating-portable-data",
		generatedAt: sources.generatedAt ?? new Date().toISOString(),
		sessions: sources.sessions.map((session) => ({
			data: session.data,
			metadata: metadataForSession(session.data, session.metadata),
		})),
		storage: sources.storage,
		sandbox: sources.sandbox,
	};
}

export async function buildKeatingPortableDataBundle(options: { includeSandbox?: boolean } = {}): Promise<KeatingPortableDataBundle> {
	await getInitPromise();
	const metadata = await sessions.getAllMetadata();
	const loaded = await Promise.all(metadata.map(async (entry) => {
		const data = await sessions.loadSession(entry.id) as SessionData | null;
		return data ? { data, metadata: metadataForSession(data, entry) } : null;
	}));
	const sandbox = options.includeSandbox === false
		? undefined
		: await buildSandboxPortableBundle().catch(() => undefined);
	return buildKeatingPortableDataBundleFromSources({
		sessions: loaded.filter((entry): entry is KeatingPortableSession => Boolean(entry)),
		storage: await keatingStorage.exportPortableData(),
		sandbox,
	});
}

export async function importKeatingPortableDataBundle(bundle: KeatingPortableDataBundle): Promise<KeatingPortableImportResult> {
	const parsed = parseKeatingPortableDataBundle(bundle);
	await getInitPromise();
	let sessionCount = 0;
	for (const session of parsed.sessions ?? []) {
		await sessions.save(session.data, metadataForSession(session.data, session.metadata));
		sessionCount += 1;
	}
	const storageResult = await keatingStorage.importPortableData(parsed.storage);
	let sandboxFilesImported = 0;
	let sandboxSnapshotsImported = 0;
	let sandboxCommitsImported = 0;
	if (parsed.sandbox) {
		const sandboxResult = await importSandboxPortableBundle(parsed.sandbox);
		sandboxFilesImported = sandboxResult.filesImported;
		sandboxSnapshotsImported = sandboxResult.snapshotsImported;
		sandboxCommitsImported = sandboxResult.commitsImported;
	}
	if (typeof window !== "undefined") {
		window.dispatchEvent(new CustomEvent("keating:sessions-changed"));
	}
	return {
		...storageResult,
		sessions: sessionCount,
		sandboxFilesImported,
		sandboxSnapshotsImported,
		sandboxCommitsImported,
	};
}

