function canSeeSubmission(
  course: Course,
  viewer: CourseMember,
  submission: CourseSubmission,
): boolean {
  if (submission.accountId === viewer.accountId) return true;
  if (roleCanTeach(viewer.role)) {
    return memberFor(course, submission.accountId).teacherAccess === "full";
  }
  return submission.sharedWithPeers;
}

function canSeeAssignmentSubmission(
  course: Course,
  viewer: CourseMember,
  submission: CourseAssignmentSubmission,
): boolean {
  if (submission.accountId === viewer.accountId) return true;
  if (roleCanTeach(viewer.role)) {
    return memberFor(course, submission.accountId).teacherAccess === "full";
  }
  return submission.sharedWithPeers;
}

function canSeeMemberPrivateState(
  viewer: CourseMember,
  member: CourseMember,
): boolean {
  if (member.accountId === viewer.accountId) return true;
  return (
    roleCanTeach(viewer.role) &&
    !roleCanTeach(member.role) &&
    member.teacherAccess === "full"
  );
}

function canSeeMemberConsentState(
  viewer: CourseMember,
  member: CourseMember,
): boolean {
  if (member.accountId === viewer.accountId) return true;
  return roleCanTeach(viewer.role) && !roleCanTeach(member.role);
}

function projectMemberForViewer(
  course: Course,
  viewer: CourseMember,
  member: CourseMember,
): CourseMember {
  if (canSeeMemberPrivateState(viewer, member)) return structuredClone(member);
  return {
    accountId: member.accountId,
    displayName: member.displayName,
    role: member.role,
    teacherAccess: canSeeMemberConsentState(viewer, member)
      ? member.teacherAccess
      : "private",
    // CourseMember remains schema-compatible without revealing member-specific timestamps.
    joinedAt: course.createdAt,
    progress: {
      completedLessonIds: [],
      lastActiveAt: course.createdAt,
    },
  };
}

export function projectCourseForViewer(
  course: Course,
  viewerAccountId: string,
): CourseViewerSnapshot {
  const viewer = memberFor(course, viewerAccountId);
  const projected = structuredClone(course);
  projected.materials = projected.materials.map((material) => {
    const { storageKey: _storageKey, ...publicMaterial } = material;
    return publicMaterial;
  });
  projected.members = course.members.map((member) =>
    projectMemberForViewer(course, viewer, member),
  );
  projected.submissions = projected.submissions.filter((submission) =>
    canSeeSubmission(course, viewer, submission),
  );
  projected.assignmentSubmissions = projected.assignmentSubmissions.filter(
    (submission) => canSeeAssignmentSubmission(course, viewer, submission),
  );
  projected.activity = projected.activity.filter((item) => {
    const member = course.members.find(
      (candidate) => candidate.accountId === item.accountId,
    );
    return member ? canSeeMemberPrivateState(viewer, member) : false;
  });
  return {
    course: projected,
    viewer: structuredClone(viewer),
    permissions: permissionsFor(course, viewerAccountId),
  };
}
import { useCallback, useEffect, useState } from "react";

export interface CoursesAccount {
	id: string;
	displayName: string;
	mode: "development" | "local" | "hosted";
}

export type CoursesAccessState =
	| { status: "loading" }
	| { status: "unavailable"; error: string; recovery: "account" | "start-server" | "retry" }
	| { status: "ready"; account: CoursesAccount };

export function describeCourseAccessFailure(
	status: number,
	body: { statusMessage?: unknown; message?: unknown; error?: unknown; data?: { code?: unknown } },
): Extract<CoursesAccessState, { status: "unavailable" }> {
	const code = typeof body.data?.code === "string" ? body.data.code : undefined;
	if (code === "notorganic_auth_adapter_unavailable") {
		return {
			status: "unavailable",
			error: typeof body.statusMessage === "string" ? body.statusMessage : "Your hosted course account could not be verified.",
			recovery: "account",
		};
	}
	if (status === 404) {
		return {
			status: "unavailable",
			error: "The course API is not running. Start the full Keating web task, then retry.",
			recovery: "start-server",
		};
	}
	const message = [body.statusMessage, body.message, body.error].find((value): value is string => typeof value === "string" && value.trim().length > 0);
	return {
		status: "unavailable",
		error: message ?? "Your course workspace is unavailable.",
		recovery: "retry",
	};
}

export function useCoursesAccess(): [CoursesAccessState, () => void] {
	const [nonce, setNonce] = useState(0);
	const [state, setState] = useState<CoursesAccessState>({ status: "loading" });
	useEffect(() => {
		let cancelled = false;
		setState({ status: "loading" });
		fetch("/api/courses/session")
			.then(async (response) => {
				const body = await response.json().catch(() => ({}));
				if (!response.ok) {
					throw describeCourseAccessFailure(response.status, body);
				}
				return body.account as CoursesAccount;
			})
			.then((account) => {
				if (!cancelled) setState({ status: "ready", account });
			})
			.catch((error) => {
				if (!cancelled) setState(
					error?.status === "unavailable"
						? error as Extract<CoursesAccessState, { status: "unavailable" }>
						: { status: "unavailable", error: error instanceof Error ? error.message : "Your course workspace is unavailable.", recovery: "retry" },
				);
			});
		return () => {
			cancelled = true;
		};
	}, [nonce]);
	return [state, useCallback(() => setNonce((value) => value + 1), [])];
}
