}

export interface LearnerSession {
  id: string;
  title: string;
  createdAt: string;
  updatedAt: string;
  /** A fork keeps a source session and message instead of duplicating hidden history. */
  parentSessionId?: string;
  forkedFromMessageId?: string;
  activeBranchId: string;
  branches: LearnerBranch[];
  messages: LearnerMessage[];
  model?: {
    provider: string;
