export const REQUIRED_CONTRAST: readonly ContrastRequirement[] = [
  { foreground: "text", background: "surface", threshold: 4.5, purpose: "normal-text" },
  { foreground: "mutedText", background: "surface", threshold: 4.5, purpose: "normal-text" },
  { foreground: "onAccent", background: "accent", threshold: 4.5, purpose: "normal-text" },
