    expect(keatingDesignContract.native.baseUnitDp).toBe(4);
    expect(keatingDesignContract.native.minimumTouchTargetDp).toBe(44);
    expect(keatingDesignContract.native.regularControlMinDp).toBeGreaterThanOrEqual(44);
  });

