import {
  DEFAULT_POLICY,
  buildConceptMap,
  buildLessonPlan,
  generateQuiz,
  lessonPlanToMarkdown,
  quizToMarkdown,
  resolveTopic,
} from "./keating-core";
import type { GeneratedArtifactKind } from "./types";

export interface GeneratedLearningArtifact {
  kind: GeneratedArtifactKind;
  topic: string;
  title: string;
  content: string;
}

export function generateLearningArtifact(
  topicName: string,
  kind: GeneratedArtifactKind,
  seed = 42,
): GeneratedLearningArtifact {
  const topic = resolveTopic(topicName.trim());

  if (kind === "study-plan") {
    return {
      kind,
      topic: topic.title,
      title: `Study plan: ${topic.title}`,
      content: lessonPlanToMarkdown(buildLessonPlan(topic.title, DEFAULT_POLICY)),
    };
  }

  if (kind === "concept-map") {
    return {
      kind,
      topic: topic.title,
      title: `Concept map: ${topic.title}`,
      content: `# Concept Map: ${topic.title}\n\n\`\`\`mermaid\n${buildConceptMap(topic.title)}\n\`\`\`\n`,
    };
  }

  const quiz = generateQuiz(topic.title, seed);
  const answerLines = quiz.questions.flatMap((question) => [
    `## ${question.id}`,
    `||${question.correctAnswer} ${question.explanation}||`,
    "",
  ]);
  return {
    kind,
    topic: topic.title,
    title: `Practice quiz: ${topic.title}`,
    content: `${quizToMarkdown(quiz)}\n# Check your answers\n\nTry every question before revealing these.\n\n${answerLines.join("\n").trim()}\n`,
  };
}
/**
 * In-memory answers for interactive cards.
 *
 * Cards live inside the chat FlatList, which unmounts rows that scroll far off
 * screen. Keeping submitted answers here — keyed by message id and position —
 * means a card the learner already completed comes back completed rather than
 * blank. The submitted answers are also echoed into the transcript as a user
 * turn, so nothing durable is lost when the app restarts.
 */
const store = new Map<string, unknown>();

export function cardKey(messageId: string, index: number): string {
  return `${messageId}:${index}`;
}

export function readCardState<T>(key: string): T | undefined {
  return store.get(key) as T | undefined;
}

export function writeCardState(key: string, value: unknown): void {
  store.set(key, value);
}

/** Drops every remembered answer; used when local learning data is cleared. */
export function clearCardState(): void {
  store.clear();
}
