                    </Pressable>
                  </View>
                </View>
              ) : null}
            </View>
          );
        })}
        {state.artifacts.length === 0 ? (
          <EmptyState
            title="Your library is empty"
            body="Save a useful Keating response from a lesson. It will stay available here, even after you switch sessions."
