import { expect, test } from "bun:test";
import { keatingDesignContract } from "@keating/design-contract";
import { projectNativeTheme, radii, spacing } from "../src/constants/theme";

test("native theme projection preserves the contract's light and dark semantic anchors", () => {
  for (const name of ["light", "dark"] as const) {
    const projected = projectNativeTheme(name);
    const contract = keatingDesignContract.themes[name].colors;
    expect(projected.colors.background).toBe(contract.surface);
    expect(projected.colors.surface).toBe(contract.surfaceRaised);
    expect(projected.colors.text).toBe(contract.text);
    expect(projected.colors.primary).toBe(contract.accent);
    expect(projected.colors.error).toBe(contract.danger);
  }
});

test("native density stays on the contract grid and never reduces shared targets below 44dp", () => {
  expect(spacing.xxs).toBe(keatingDesignContract.native.baseUnitDp / 2);
  expect(spacing.xl).toBe(keatingDesignContract.native.spacingDp.xl);
  expect(radii.sm).toBe(keatingDesignContract.native.radiiDp.control);
  expect(radii.md).toBe(keatingDesignContract.native.radiiDp.panel);
  expect(keatingDesignContract.native.minimumTouchTargetDp).toBe(44);
});

test("native shell references canonical Keating identity rather than legacy owl artwork", async () => {
  const root = await Bun.file("src/app/_layout.tsx").text();
  const tutor = await Bun.file("src/app/(tabs)/index.tsx").text();
  expect(root).toContain("assets/brand/logo-lockup.png");
  expect(tutor).toContain("assets/brand/logo-lockup.png");
  expect(root).not.toContain("keating-mark");
  expect(tutor).not.toContain("introMark");
});

